function planning_json(int $status,array $payload): never

{

    http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;

}

function planning_ok(string $message,array $data=[]): never { planning_json(200,['ok'=>true,'message'=>$message,'data'=>$data]); }

function planning_ai_key(PDO $db): string
{
    $q=$db->query("SELECT api_key_ciphertext FROM ai_provider_settings WHERE id=1 AND provider='openrouter'");$cipher=(string)($q->fetchColumn()?:'');if($cipher==='')throw new DomainException('AI planning is unavailable until an administrator configures the existing OpenRouter provider.');if(!function_exists('openssl_decrypt'))throw new DomainException('AI planning requires the PHP OpenSSL extension.');$raw=base64_decode($cipher,true);if($raw===false||strlen($raw)<=28)throw new DomainException('The configured AI provider key is unavailable. Ask an administrator to check its settings.');$secret=(string)getenv('SHULELITE_ENCRYPTION_KEY');if(strlen($secret)<32)throw new DomainException('The AI provider encryption key is not configured on this server.');$key=hash('sha256',$secret,true);$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',$key,OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),'ShuleLite OpenRouter API key');if(!is_string($plain)||$plain==='')throw new DomainException('The AI provider key could not be decrypted. Ask an administrator to verify its encryption settings.');return $plain;
}

function planning_ai_json(PDO $db,string $system,string $prompt): array
{
    if(!function_exists('curl_init'))throw new DomainException('AI planning requires the PHP cURL extension.');$key=planning_ai_key($db);$q=$db->query("SELECT model FROM ai_provider_settings WHERE id=1 AND provider='openrouter'");$model=(string)($q->fetchColumn()?:'openai/gpt-4o-mini');$fallback=['openai/gpt-4o-mini','~anthropic/claude-haiku-latest','google/gemini-3.8-flash','~moonshotai/kimi-latest','~z-ai/glm-latest'];$models=array_values(array_unique(array_merge([$model],$fallback)));$payload=['models'=>$models,'temperature'=>0.35,'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$prompt]]];$ch=curl_init('https://openrouter.ai/api/v1/chat/completions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>75,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key,'Content-Type: application/json','HTTP-Referer: '.((isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost')),'X-Title: ShuleLite Teaching Planner'],CURLOPT_POSTFIELDS=>json_encode($payload,JSON_THROW_ON_ERROR)]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);if($body===false)throw new DomainException('The AI provider could not be reached: '.mb_substr($error,0,240));$response=json_decode($body,true);if($status<200||$status>=300)throw new DomainException(mb_substr((string)($response['error']['message']??'The AI provider returned an error.'),0,400));$content=trim((string)($response['choices'][0]['message']['content']??''));$content=preg_replace('/^```(?:json)?\s*|\s*```$/i','',$content);$data=json_decode($content,true);if(!is_array($data))throw new DomainException('The AI provider did not return valid structured content. Try again or draft manually.');return ['data'=>$data,'model'=>(string)($response['model']??$model)];
}

if(!signed_in())planning_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);

require_sign_in();

if(!empty($_SESSION['must_change_password']))planning_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);

$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];

$schoolId=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$schoolId||$schoolId<1)planning_json(422,['ok'=>false,'message'=>'Choose a school.']);

$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$schoolId]);if(!$q->fetchColumn())planning_json(403,['ok'=>false,'message'=>'That school is outside your access.']);

$leaders=['director','sub_director','headteacher','head_academic','assistant_academic'];$teacherRoles=['teacher','head_academic','assistant_academic','headteacher'];$canReview=in_array($role,$leaders,true);

function planning_assignment(PDO $db,int $user,int $school,int $class,int $subject): bool

{

    $q=$db->prepare('SELECT 1 FROM teacher_assignments a JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects s ON s.class_id=c.id AND s.name=a.subject WHERE a.user_id=? AND a.school_id=? AND c.id=? AND s.id=? AND a.active=1 LIMIT 1 FOR UPDATE');$q->execute([$user,$school,$class,$subject]);return(bool)$q->fetchColumn();

}

function planning_department_scope(PDO $db,int $user,int $school,int $subject): bool

{

    $q=$db->prepare("SELECT 1 FROM department_subjects ds JOIN departments d ON d.id=ds.department_id AND d.school_id=ds.school_id WHERE ds.school_id=? AND ds.class_subject_id=? AND d.department_type='academic' AND d.head_user_id=? LIMIT 1 FOR UPDATE");$q->execute([$school,$subject,$user]);return(bool)$q->fetchColumn();

}

function planning_audit(PDO $db,int $uid,string $action,string $entity,int $id,array $details): void

{

    $q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$action,$entity,$id,json_encode($details,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)]);

}

function planning_report_snapshot(PDO $db,int $school,int $teacher,string $start,string $end): array
{
    $q=$db->prepare("SELECT COUNT(DISTINCT lp.id) lessons_planned,COUNT(DISTINCT CASE WHEN lp.status IN ('draft','submitted','returned') THEN lp.id END) outstanding_plans FROM lesson_plans lp WHERE lp.school_id=? AND lp.teacher_id=? AND lp.scheduled_for BETWEEN ? AND ?");$q->execute([$school,$teacher,$start,$end]);$snapshot=$q->fetch()?:[];
    $q=$db->prepare("SELECT COUNT(*) lessons_delivered,COALESCE(SUM(periods_delivered),0) periods_delivered,SUM(challenges IS NOT NULL AND challenges<>'') teaching_challenges,SUM(intervention IS NOT NULL AND intervention<>'') interventions_recorded FROM teaching_records WHERE school_id=? AND teacher_id=? AND taught_on BETWEEN ? AND ?");$q->execute([$school,$teacher,$start,$end]);$teaching=$q->fetch()?:[];$snapshot=array_merge($snapshot,$teaching);
    $q=$db->prepare('SELECT attendance_status,COUNT(*) total FROM pupil_attendance WHERE school_id=? AND recorded_by=? AND attendance_date BETWEEN ? AND ? GROUP BY attendance_status');$q->execute([$school,$teacher,$start,$end]);$attendance=[];foreach($q->fetchAll() as $row)$attendance[$row['attendance_status']]=(int)$row['total'];$snapshot['attendance_by_status']=$attendance;$snapshot['attendance_marks']=array_sum($attendance);$q=$db->prepare('SELECT pa.attendance_status,COUNT(*) total FROM pupil_attendance pa JOIN pupils p ON p.id=pa.pupil_id AND p.school_id=pa.school_id WHERE pa.school_id=? AND pa.attendance_date BETWEEN ? AND ? AND EXISTS(SELECT 1 FROM teacher_assignments ta WHERE ta.school_id=pa.school_id AND ta.user_id=? AND ta.class_level=p.class_level AND ta.active=1) GROUP BY pa.attendance_status');$q->execute([$school,$start,$end,$teacher]);$classAttendance=[];foreach($q->fetchAll() as $row)$classAttendance[$row['attendance_status']]=(int)$row['total'];$snapshot['assigned_class_attendance_by_status']=$classAttendance;$snapshot['assigned_class_attendance_marks']=array_sum($classAttendance);
    $q=$db->prepare("SELECT COUNT(DISTINCT x.id) FROM school_exams x WHERE x.school_id=? AND x.status IN ('results_open','results_published') AND x.exam_date BETWEEN ? AND ? AND EXISTS(SELECT 1 FROM pupil_results r JOIN school_classes c ON c.school_id=r.school_id AND c.name=r.class_level JOIN school_class_subjects cs ON cs.class_id=c.id AND cs.name=r.subject JOIN teacher_assignments a ON a.school_id=r.school_id AND a.class_level=r.class_level AND a.subject=r.subject AND a.user_id=? AND a.active=1 WHERE r.school_id=x.school_id AND r.exam_name=x.name AND r.academic_year=x.academic_year AND (x.class_id IS NULL OR x.class_id=c.id) AND (x.subject_id IS NULL OR x.subject_id=cs.id))");$q->execute([$school,$start,$end,$teacher]);$snapshot['assessments_conducted']=(int)$q->fetchColumn();
    $q=$db->prepare("SELECT sw.id scheme_id,sw.title,sw.academic_year,sw.term,sc.name class_name,cs.name subject_name,(SELECT COUNT(*) FROM lesson_plans lp JOIN scheme_topics st ON st.id=lp.topic_id AND st.scheme_id=sw.id WHERE lp.school_id=sw.school_id AND lp.teacher_id=? AND lp.scheme_id=sw.id AND lp.scheduled_for BETWEEN ? AND ?) lessons_planned,(SELECT COUNT(DISTINCT st.id) FROM lesson_plans lp JOIN scheme_topics st ON st.id=lp.topic_id AND st.scheme_id=sw.id WHERE lp.school_id=sw.school_id AND lp.teacher_id=? AND lp.scheme_id=sw.id AND lp.scheduled_for BETWEEN ? AND ?) planned_topics,(SELECT COUNT(DISTINCT tr.lesson_plan_id) FROM teaching_records tr JOIN lesson_plans lp ON lp.id=tr.lesson_plan_id AND lp.school_id=tr.school_id JOIN scheme_topics st ON st.id=lp.topic_id AND st.scheme_id=sw.id WHERE tr.school_id=sw.school_id AND tr.teacher_id=? AND lp.scheme_id=sw.id AND tr.taught_on BETWEEN ? AND ?) lessons_delivered,(SELECT COUNT(DISTINCT st.id) FROM teaching_records tr JOIN lesson_plans lp ON lp.id=tr.lesson_plan_id AND lp.school_id=tr.school_id JOIN scheme_topics st ON st.id=lp.topic_id AND st.scheme_id=sw.id WHERE tr.school_id=sw.school_id AND tr.teacher_id=? AND lp.scheme_id=sw.id AND tr.taught_on BETWEEN ? AND ?) topics_delivered,(SELECT COALESCE(SUM(tr.periods_delivered),0) FROM teaching_records tr JOIN lesson_plans lp ON lp.id=tr.lesson_plan_id AND lp.school_id=tr.school_id WHERE tr.school_id=sw.school_id AND tr.teacher_id=? AND lp.scheme_id=sw.id AND tr.taught_on BETWEEN ? AND ?) periods_delivered FROM schemes_of_work sw JOIN school_classes sc ON sc.id=sw.class_id AND sc.school_id=sw.school_id JOIN school_class_subjects cs ON cs.id=sw.subject_id AND cs.class_id=sc.id WHERE sw.school_id=? AND sw.status='approved' AND (EXISTS(SELECT 1 FROM lesson_plans lp WHERE lp.school_id=sw.school_id AND lp.teacher_id=? AND lp.scheme_id=sw.id AND lp.scheduled_for BETWEEN ? AND ?) OR EXISTS(SELECT 1 FROM teaching_records tr JOIN lesson_plans lp ON lp.id=tr.lesson_plan_id AND lp.school_id=tr.school_id WHERE tr.school_id=sw.school_id AND tr.teacher_id=? AND lp.scheme_id=sw.id AND tr.taught_on BETWEEN ? AND ?)) AND (sw.created_by=? OR EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.school_id=sw.school_id AND a.user_id=? AND a.active=1 AND a.class_level=sc.name AND a.subject=cs.name)) ORDER BY sw.academic_year DESC,sw.term,sc.name,cs.name");$q->execute([$teacher,$start,$end,$teacher,$start,$end,$teacher,$start,$end,$teacher,$start,$end,$teacher,$start,$end,$school,$teacher,$start,$end,$teacher,$start,$end,$teacher,$teacher]);$snapshot['curriculum_coverage']=$q->fetchAll();$snapshot['period_start']=$start;$snapshot['period_end']=$end;return array_map(static fn($value)=>is_numeric($value)?(int)$value:$value,$snapshot);
}

if($_SERVER['REQUEST_METHOD']==='GET'){

    $view=(string)($_GET['view']??'overview');

    if($view==='catalog'){

        $q=$db->prepare('SELECT c.id,c.name FROM school_classes c WHERE c.school_id=? ORDER BY c.name');$q->execute([$schoolId]);$classes=$q->fetchAll();$q=$db->prepare('SELECT s.id,s.class_id,s.name FROM school_class_subjects s JOIN school_classes c ON c.id=s.class_id WHERE c.school_id=? ORDER BY c.name,s.name');$q->execute([$schoolId]);$subjects=$q->fetchAll();

        if($role==='teacher'){$q=$db->prepare('SELECT DISTINCT c.id class_id,s.id subject_id FROM teacher_assignments a JOIN school_classes c ON c.school_id=a.school_id AND c.name=a.class_level JOIN school_class_subjects s ON s.class_id=c.id AND s.name=a.subject WHERE a.user_id=? AND a.school_id=? AND a.active=1');$q->execute([$uid,$schoolId]);$assignments=$q->fetchAll();$noteScope=" AND EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=? AND a.active=1 AND a.class_level=n.class_level AND (n.subject IS NULL OR a.subject=n.subject))";}else{$assignments=[];$noteScope='';}$q=$db->prepare("SELECT n.id,n.subtopic,n.class_level,n.subject,n.topic,n.source,n.note_type FROM learning_notes n WHERE n.status='published' AND ((n.note_type='central' AND n.school_id IS NULL) OR (n.note_type='teacher' AND n.school_id=?)) AND EXISTS(SELECT 1 FROM school_classes c WHERE c.school_id=? AND c.name=n.class_level) AND (n.subject IS NULL OR EXISTS(SELECT 1 FROM school_classes c JOIN school_class_subjects cs ON cs.class_id=c.id WHERE c.school_id=? AND c.name=n.class_level AND cs.name=n.subject))$noteScope ORDER BY n.class_level,n.subject,n.topic,n.subtopic");if($role==='teacher')$q->execute([$schoolId,$schoolId,$schoolId,$uid,$schoolId]);else $q->execute([$schoolId,$schoolId,$schoolId]);$resources=$q->fetchAll();

        $q=$db->prepare('SELECT st.id,st.class_id,st.name FROM school_streams st JOIN school_classes c ON c.id=st.class_id WHERE c.school_id=? ORDER BY c.name,st.name');$q->execute([$schoolId]);$streams=$q->fetchAll();
        planning_ok('Academic catalog loaded.',['classes'=>$classes,'subjects'=>$subjects,'assignments'=>$assignments,'resources'=>$resources,'streams'=>$streams,'can_review'=>$canReview]);

    }

    if($view==='scheme'){

        $id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id)planning_json(422,['ok'=>false,'message'=>'Choose a scheme.']);$q=$db->prepare('SELECT sw.*,sc.name class_name,ss.name subject_name FROM schemes_of_work sw JOIN school_classes sc ON sc.id=sw.class_id JOIN school_class_subjects ss ON ss.id=sw.subject_id WHERE sw.id=? AND sw.school_id=?');$q->execute([$id,$schoolId]);$scheme=$q->fetch();$visible=$scheme&&($scheme['created_by']==$uid||$canReview||($role==='department_head'&&planning_department_scope($db,$uid,$schoolId,(int)$scheme['subject_id']))||($scheme['status']==='approved'&&planning_assignment($db,$uid,$schoolId,(int)$scheme['class_id'],(int)$scheme['subject_id'])));if(!$visible)planning_json(404,['ok'=>false,'message'=>'Scheme not found in this school.']);$q=$db->prepare('SELECT id,sequence_no,week_number,topic,subtopic,learning_objectives,teaching_activities,resources,assessment_methods,periods_planned FROM scheme_topics WHERE scheme_id=? ORDER BY sequence_no');$q->execute([$id]);planning_ok('Scheme details loaded.',['scheme'=>$scheme,'topics'=>$q->fetchAll()]);

    }

    if($view==='coverage'){

        $params=[$schoolId];$scope='';if(in_array($role,['teacher','assistant_academic'],true)){$scope=' AND (sw.created_by=? OR EXISTS (SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=sw.school_id AND a.active=1 AND a.class_level=sc.name AND a.subject=ss.name))';$params[]=$uid;$params[]=$uid;}elseif($role==='department_head'){$scope=" AND EXISTS(SELECT 1 FROM department_subjects ds JOIN departments d ON d.id=ds.department_id AND d.school_id=ds.school_id WHERE ds.school_id=sw.school_id AND ds.class_subject_id=sw.subject_id AND d.department_type='academic' AND d.head_user_id=?)";$params[]=$uid;}

        $q=$db->prepare("SELECT sw.id scheme_id,sw.title,sw.academic_year,sw.term,sw.status,sc.name class_name,ss.name subject_name,COUNT(DISTINCT st.id) planned_topics,COUNT(DISTINCT CASE WHEN tr.id IS NOT NULL THEN st.id END) delivered_topics,(SELECT COALESCE(SUM(tr2.periods_delivered),0) FROM lesson_plans lp2 JOIN teaching_records tr2 ON tr2.lesson_plan_id=lp2.id AND tr2.school_id=sw.school_id WHERE lp2.scheme_id=sw.id) periods_delivered,(SELECT COALESCE(SUM(st2.periods_planned),0) FROM scheme_topics st2 WHERE st2.scheme_id=sw.id) periods_planned FROM schemes_of_work sw JOIN school_classes sc ON sc.id=sw.class_id JOIN school_class_subjects ss ON ss.id=sw.subject_id LEFT JOIN scheme_topics st ON st.scheme_id=sw.id LEFT JOIN lesson_plans lp ON lp.topic_id=st.id AND lp.status='completed' LEFT JOIN teaching_records tr ON tr.lesson_plan_id=lp.id AND tr.school_id=sw.school_id WHERE sw.school_id=? AND sw.status='approved' $scope GROUP BY sw.id ORDER BY sw.academic_year DESC,sw.term,sc.name,ss.name");$q->execute($params);$rows=$q->fetchAll();foreach($rows as &$row){$row['coverage_percent']=(int)$row['planned_topics']?round(100*(int)$row['delivered_topics']/(int)$row['planned_topics'],1):0;}unset($row);planning_ok('Coverage loaded.',['coverage'=>$rows]);

    }

    if($view==='stream_coverage'){
        $params=[$schoolId];$scope='';
        if($role==='teacher'){$scope=' AND lp.teacher_id=?';$params[]=$uid;}
        elseif($role==='department_head'){$scope=" AND EXISTS(SELECT 1 FROM department_subjects ds JOIN departments d ON d.id=ds.department_id AND d.school_id=ds.school_id WHERE ds.school_id=sw.school_id AND ds.class_subject_id=sw.subject_id AND d.department_type='academic' AND d.head_user_id=?)";$params[]=$uid;}
        elseif(in_array($role,['assistant_academic'],true)){$scope=' AND (lp.teacher_id=? OR sw.created_by=?)';$params[]=$uid;$params[]=$uid;}
        elseif(!$canReview&&!in_array($role,['director','sub_director'],true))planning_json(403,['ok'=>false,'message'=>'Your role cannot view stream coverage.']);
        $q=$db->prepare("SELECT lp.id lesson_id,lp.stream_id,COALESCE(stm.name,'Unassigned stream') stream_name,sw.id scheme_id,sw.title scheme_title,sw.academic_year,sw.term,sc.name class_name,ss.name subject_name,st.topic,lp.title lesson_title,lp.scheduled_for,lp.status,(SELECT COUNT(*) FROM teaching_records tr WHERE tr.lesson_plan_id=lp.id AND tr.school_id=lp.school_id) teaching_records,(SELECT COALESCE(SUM(tr.periods_delivered),0) FROM teaching_records tr WHERE tr.lesson_plan_id=lp.id AND tr.school_id=lp.school_id) periods_delivered,(SELECT MAX(tr.taught_on) FROM teaching_records tr WHERE tr.lesson_plan_id=lp.id AND tr.school_id=lp.school_id) last_taught FROM lesson_plans lp JOIN schemes_of_work sw ON sw.id=lp.scheme_id AND sw.school_id=lp.school_id JOIN school_classes sc ON sc.id=sw.class_id AND sc.school_id=sw.school_id JOIN school_class_subjects ss ON ss.id=sw.subject_id AND ss.class_id=sc.id JOIN scheme_topics st ON st.id=lp.topic_id LEFT JOIN school_streams stm ON stm.id=lp.stream_id AND stm.class_id=sc.id WHERE lp.school_id=? AND sw.status='approved' $scope ORDER BY sc.name,COALESCE(stm.name,'Unassigned stream'),ss.name,lp.scheduled_for,lp.id");$q->execute($params);planning_ok('Stream coverage loaded.',['coverage'=>$q->fetchAll()]);
    }

    if($view==='reports'){

        $start=(string)($_GET['period_start']??date('Y-m-01'));$end=(string)($_GET['period_end']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)||$start>$end||(strtotime($end)-strtotime($start))>366*86400)planning_json(422,['ok'=>false,'message'=>'Choose a valid report period of no more than 367 days.']);

        $summary=planning_report_snapshot($db,$schoolId,$uid,$start,$end);

        $q=$db->prepare('SELECT r.id,r.report_type,r.period_start,r.period_end,r.narrative,r.challenges,r.interventions,r.recommendations,r.activity_snapshot,r.status,r.review_feedback,r.reviewed_at,r.teacher_id,r.created_at,u.name teacher_name FROM teacher_reports r JOIN users u ON u.id=r.teacher_id WHERE r.school_id=? AND (r.teacher_id=? OR ?) ORDER BY r.period_start DESC,r.updated_at DESC LIMIT 100');$q->execute([$schoolId,$uid,$canReview?1:0]);$reports=$q->fetchAll();

        planning_ok('Teacher reports loaded.',['summary'=>$summary,'reports'=>$reports,'can_review'=>$canReview,'role'=>$role]);

    }

    $q=$db->prepare("SELECT sw.id,sw.title,sw.academic_year,sw.term,sw.curriculum,sw.status,sw.version,sw.created_by,sw.reviewed_by,sw.reviewed_at,sw.review_feedback,sc.name class_name,ss.name subject_name,u.name teacher_name,COUNT(DISTINCT st.id) topic_count FROM schemes_of_work sw JOIN school_classes sc ON sc.id=sw.class_id JOIN school_class_subjects ss ON ss.class_id=sc.id AND ss.id=sw.subject_id JOIN users u ON u.id=sw.created_by LEFT JOIN scheme_topics st ON st.scheme_id=sw.id WHERE sw.school_id=? AND (sw.created_by=? OR ? OR (sw.status='approved' AND EXISTS (SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=sw.school_id AND a.active=1 AND a.class_level=sc.name AND a.subject=ss.name)) OR EXISTS(SELECT 1 FROM department_subjects ds JOIN departments d ON d.id=ds.department_id AND d.school_id=ds.school_id WHERE ds.school_id=sw.school_id AND ds.class_subject_id=sw.subject_id AND d.department_type='academic' AND d.head_user_id=?)) GROUP BY sw.id ORDER BY sw.updated_at DESC LIMIT 200");$q->execute([$schoolId,$uid,$canReview?1:0,$uid,$uid]);$schemes=$q->fetchAll();$q=$db->prepare("SELECT lp.id,lp.teacher_id,lp.title,lp.objectives,lp.introduction,lp.activities,lp.materials,lp.differentiation,lp.assessment,lp.stream_id,stm.name stream_name,lp.scheduled_for,lp.status,lp.review_feedback,lp.scheme_id,lp.topic_id,sw.title scheme_title,st.topic,sc.name class_name,ss.name subject_name,u.name teacher_name FROM lesson_plans lp JOIN schemes_of_work sw ON sw.id=lp.scheme_id JOIN scheme_topics st ON st.id=lp.topic_id JOIN school_classes sc ON sc.id=sw.class_id JOIN school_class_subjects ss ON ss.class_id=sc.id AND ss.id=sw.subject_id LEFT JOIN school_streams stm ON stm.id=lp.stream_id AND stm.class_id=sw.class_id JOIN users u ON u.id=lp.teacher_id WHERE lp.school_id=? AND (lp.teacher_id=? OR ? OR EXISTS(SELECT 1 FROM department_subjects ds JOIN departments d ON d.id=ds.department_id AND d.school_id=ds.school_id WHERE ds.school_id=sw.school_id AND ds.class_subject_id=sw.subject_id AND d.department_type='academic' AND d.head_user_id=?)) ORDER BY lp.scheduled_for DESC,lp.updated_at DESC LIMIT 200");$q->execute([$schoolId,$uid,$canReview?1:0,$uid]);$lessons=$q->fetchAll();if($lessons){$lessonIds=array_map('intval',array_column($lessons,'id'));$marks=implode(',',array_fill(0,count($lessonIds),'?'));$q=$db->prepare("SELECT lr.lesson_plan_id,n.id,n.subtopic,n.topic,n.source FROM lesson_plan_resources lr JOIN learning_notes n ON n.id=lr.learning_note_id WHERE lr.school_id=? AND lr.lesson_plan_id IN ($marks) ORDER BY n.subtopic");$q->execute([$schoolId,...$lessonIds]);$links=[];foreach($q->fetchAll() as $link)$links[(int)$link['lesson_plan_id']][]=$link;foreach($lessons as &$lesson)$lesson['library_resources']=$links[(int)$lesson['id']]??[];unset($lesson);}

    planning_ok('Planning records loaded.',['schemes'=>$schemes,'lessons'=>$lessons,'can_review'=>$canReview,'role'=>$role]);

}

if($_SERVER['REQUEST_METHOD']!=='POST')planning_json(405,['ok'=>false,'message'=>'Method not allowed.']);

if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))planning_json(400,['ok'=>false,'message'=>'Your session expired. Refresh the page and try again.']);

$action=(string)($_POST['action']??'');

