        if(!in_array($role,$teacherRoles,true))planning_json(403,['ok'=>false,'message'=>'Your role cannot confirm teaching records.']);$lessonId=(int)($_POST['lesson_id']??0);$taught=(string)($_POST['taught_on']??'');$periods=filter_var($_POST['periods_delivered']??1,FILTER_VALIDATE_INT);$note=trim((string)($_POST['coverage_note']??''));$challenges=trim((string)($_POST['challenges']??''));$intervention=trim((string)($_POST['intervention']??''));if(!$lessonId||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$taught)||strtotime($taught)===false||$taught>date('Y-m-d')||$periods===false||$periods<1||$periods>20)throw new DomainException('Enter a teaching date up to today and a valid number of periods.');$db->beginTransaction();$q=$db->prepare("SELECT lp.*,sw.class_id,sw.subject_id FROM lesson_plans lp JOIN schemes_of_work sw ON sw.id=lp.scheme_id AND sw.school_id=lp.school_id WHERE lp.id=? AND lp.school_id=? AND lp.teacher_id=? AND lp.status='approved' FOR UPDATE");$q->execute([$lessonId,$schoolId,$uid]);$lesson=$q->fetch();if(!$lesson||!planning_assignment($db,$uid,$schoolId,(int)$lesson['class_id'],(int)$lesson['subject_id']))throw new DomainException('Only an assigned teacher can confirm their approved lesson plan.');$q=$db->prepare('INSERT INTO teaching_records(school_id,lesson_plan_id,teacher_id,taught_on,periods_delivered,coverage_note,challenges,intervention) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$schoolId,$lessonId,$uid,$taught,$periods,$note?:null,$challenges?:null,$intervention?:null]);$recordId=(int)$db->lastInsertId();$db->prepare("UPDATE lesson_plans SET status='completed',reflection=? WHERE id=? AND school_id=?")->execute([$note?:null,$lessonId,$schoolId]);planning_audit($db,$uid,'confirm_teaching','teaching_record',$recordId,['school_id'=>$schoolId,'lesson_plan_id'=>$lessonId,'taught_on'=>$taught,'periods_delivered'=>$periods]);$db->commit();planning_ok('Teaching record confirmed. Curriculum coverage has been updated.',['teaching_record_id'=>$recordId]);

    }

